{
  "decisions": [
    {
      "decision": "startup_constraint_direction",
      "evidence": "\"The number of generators started in a period cannot exceed the difference between the number of active generators in that period and the previous period, plus any generators that were already started.\"",
      "options": [
        "s[t,g] <= n[t,g] - n[t-1,g] + s[t-1,g] (upper bound on startups)",
        "s[t,g] >= n[t,g] - n[t-1,g] (lower bound forcing startups to cover increases)"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "s[t,g] >= n[t,g] - n[t-1,g]"
    },
    {
      "decision": "initial_period_startup_handling",
      "evidence": "\"plus any generators that were already started\" (no initial active/startup counts given)",
      "options": [
        "t=0: s[0,g] >= n[0,g] (all active units in period 0 count as started)",
        "t=0: s[0,g] <= n[0,g] with init_active=0, init_startup=0",
        "t=0: no startup constraint (startups unconstrained in first period)"
      ],
      "plausibility": [
        0.5,
        0.3,
        0.2
      ],
      "majority_option": "t=0: s[0,g] >= n[0,g] (all active units in period 0 count as started)"
    },
    {
      "decision": "startup_variable_domain",
      "evidence": "\"The number of active generators and startups must be non-negative integers\"",
      "options": [
        "NonNegativeIntegers",
        "NonNegativeReals"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "NonNegativeIntegers"
    },
    {
      "decision": "active_count_variable_domain",
      "evidence": "\"The number of active generators and startups must be non-negative integers\"",
      "options": [
        "NonNegativeIntegers",
        "NonNegativeReals"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "NonNegativeIntegers"
    },
    {
      "decision": "power_output_domain",
      "evidence": "\"the power output must be non-negative\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "reserve_margin_direction",
      "evidence": "\"The total maximum output capacity of all active generators must be at least 15% higher than the demand in each period.\"",
      "options": [
        "sum(max_output[g]*n[t,g]) >= 1.15 * demand[t]",
        "sum(max_output[g]*n[t,g]) >= demand[t] + 0.15 (absolute 15% of nothing)"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "sum(max_output[g]*n[t,g]) >= 1.15 * demand[t]"
    }
  ]
}
